export function photo(key: string): Photo {
  const p = photos[key];
  if (!p) throw new Error(`Unknown photo ${key}`);
  return p;
}
export const projectPhotos = (project: string) => Object.values(photos).filter((p) => p.project === project).sort((a, b) => (a.date < b.date ? -1 : 1));
